  `IsDeleted` tinyint(1) NOT NULL DEFAULT 0,
  `Notes` varchar(500) DEFAULT NULL,
  `UpdateDate` datetime(6) NOT NULL DEFAULT '0001-01-01 00:00:00.000000',
  PRIMARY KEY (`Id`),
  KEY `IX_CustomerOrderItems_CustomerOrderId` (`CustomerOrderId`),
  KEY `IX_CustomerOrderItems_InsertByUserId` (`InsertByUserId`),
  KEY `IX_CustomerOrderItems_ItemId` (`ItemId`),
  CONSTRAINT `FK_CustomerOrderItems_CustomerOrders_CustomerOrderId` FOREIGN KEY (`CustomerOrderId`) REFERENCES `customerorders` (`Id`),
  CONSTRAINT `FK_CustomerOrderItems_Items_ItemId` FOREIGN KEY (`ItemId`) REFERENCES `items` (`Id`),
  CONSTRAINT `FK_CustomerOrderItems_Users_InsertByUserId` FOREIGN KEY (`InsertByUserId`) REFERENCES `users` (`Id`)
